<script setup lang="ts">
/**
 * A column of items of one kind, each read, followed or picked (`design/components/list.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onBeforeUnmount, onMounted, useTemplateRef } from 'vue'

import { agentMember, chooseListItem, currentListItem, listItems } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/list.module.css'

export interface ListProps {
  /**
   * Names the list for a reader: "Notifications", not "List".
   */
  label: string
}

defineOptions({ name: 'List', inheritAttrs: false })

defineProps<ListProps>()
defineSlots<{ default?: (props: Record<string, never>) => unknown }>()
const list = useTemplateRef<HTMLElement>('list')
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'List',
    element: () => list.value,
    state: () => ({
      items: listItems(list.value, styles.primary),
      current: currentListItem(list.value, styles.primary),
    }),
    actions: {
      choose: { argument: 'id', run: (value) => chooseListItem(list.value, styles.primary, value) },
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <ul ref="list" :class="styles.list" role="list" :aria-label="label" data-member="list">
    <slot />
  </ul>
</template>
